import sys
import pandas as pd
import numpy as np
import json

# Read CSV
df = pd.read_csv(sys.argv[1])

facts = []

# Helper function to convert numpy types to Python types
def to_python(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.floating)):
        return float(val)
    return val

# 1. Top 3 entities by Revenue_TW (Rank 1, 2, 3)
top_by_revenue = df.nlargest(3, 'Revenue_TW')
for idx, row in top_by_revenue.iterrows():
    if pd.notna(row['Revenue_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "TW",
            "value": round(to_python(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

# 2. Total Revenue_TW
total_revenue_tw = df['Revenue_TW'].sum()
if pd.notna(total_revenue_tw) and total_revenue_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "TW",
        "value": round(to_python(total_revenue_tw), 2),
        "formula": "SUM(Revenue_TW)"
    })

# 3. Total Units_TW
total_units_tw = df['Units_TW'].sum()
if pd.notna(total_units_tw) and total_units_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "units",
        "period": "TW",
        "value": to_python(total_units_tw),
        "formula": "SUM(Units_TW)"
    })

# 4. Total Orders_TW
total_orders_tw = df['Orders_TW'].sum()
if pd.notna(total_orders_tw) and total_orders_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "orders",
        "period": "TW",
        "value": to_python(total_orders_tw),
        "formula": "SUM(Orders_TW)"
    })

# 5. Share_Pct for top entities
top_by_share = df.nlargest(3, 'Share_Pct')
for idx, row in top_by_share.iterrows():
    if pd.notna(row['Share_Pct']):
        facts.append({
            "entity": row['Entity'],
            "metric": "share",
            "period": "TW",
            "value": round(to_python(row['Share_Pct']), 1),
            "formula": "Share_Pct"
        })

# 6. Biggest WoW movers (top 3 by absolute WoW_Pct)
df_wow = df[df['WoW_Pct'].notna()].copy()
if len(df_wow) > 0:
    top_wow = df_wow.nlargest(3, 'WoW_Pct')
    for idx, row in top_wow.iterrows():
        if pd.notna(row['WoW_Pct']):
            facts.append({
                "entity": row['Entity'],
                "metric": "revenue",
                "period": "WoW",
                "value": round(to_python(row['WoW_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

# 7. Biggest YoY movers (top 3 by absolute YoY_Pct)
df_yoy = df[df['YoY_Pct'].notna()].copy()
if len(df_yoy) > 0:
    top_yoy = df_yoy.nlargest(3, 'YoY_Pct')
    for idx, row in top_yoy.iterrows():
        if pd.notna(row['YoY_Pct']):
            facts.append({
                "entity": row['Entity'],
                "metric": "revenue",
                "period": "YoY",
                "value": round(to_python(row['YoY_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

# 8. Total Revenue_LW and WoW for TOTAL
total_revenue_lw = df['Revenue_LW'].sum()
if pd.notna(total_revenue_lw) and total_revenue_lw > 0 and total_revenue_tw > 0:
    wow_total = (total_revenue_tw - total_revenue_lw) / total_revenue_lw * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(wow_total), 1),
        "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
    })

# 9. Total Revenue_LY and YoY for TOTAL
total_revenue_ly = df['Revenue_LY'].sum()
if pd.notna(total_revenue_ly) and total_revenue_ly > 0 and total_revenue_tw > 0:
    yoy_total = (total_revenue_tw - total_revenue_ly) / total_revenue_ly * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "YoY",
        "value": round(to_python(yoy_total), 1),
        "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
    })

# 10. Units and Orders for top entities by Revenue_TW
for idx, row in top_by_revenue.head(2).iterrows():
    if pd.notna(row['Units_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "units",
            "period": "TW",
            "value": to_python(row['Units_TW']),
            "formula": "Units_TW"
        })
    if pd.notna(row['Orders_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "orders",
            "period": "TW",
            "value": to_python(row['Orders_TW']),
            "formula": "Orders_TW"
        })

# Limit to 25 facts
facts = facts[:25]

print(json.dumps(facts))
